:"wa-597fc95e81c64459","before":{"country":"United Kingdom","county":"","city":"Bedford","area":""},"after":{"country":"England","county":"Bedfordshire","city":"Bedford","area":""},"source_url":"https://worldathletics.org/athletes/-/14542604","evidence_ids":["geo-269","geo-270"]},{"slug":"wa-8ea628083a329ae1","before":{"country":"United Kingdom","county":"","city":"Bedford","area":""},"after":{"country":"England","county":"Bedfordshire","city":"Bedford","area":""},"source_url":"https://worldathletics.org/athletes/-/14542604","evidence_ids":["geo-269","geo-270"]},{"slug":"wa-3f85be4c4b188f4e","before":{"country":"United Kingdom","county":"","city":"Manchester","area":""},"after":{"country":"England","county":"Greater Manchester","city":"Manchester","area":""},"source_url":"https://worldathletics.org/athletes/-/14542604","evidence_ids":["geo-13","geo-14"]},{"slug":"wa-a8c29e0d11f0972c","before":{"country":"United Kingdom","county":"","city":"Cambridge","area":""},"after":{"country":"England","county":"Cambridgeshire","city":"Cambridge","area":""},"source_url":"https://worldathletics.org/athletes/-/14542604","evidence_ids":["geo-317"]},{"slug":"wa-c2e2cebb3bc21b57","before":{"country":"United Kingdom","county":"","city":"Hendon","area":""},"after":{"country":"England","county":"Greater London","city":"Hendon","area":""},"source_url":"https://worldathletics.org/athletes/-/14542604","evidence_ids":["geo-318"]},{"slug":"wa-dbb8281e13981446","before":{"country":"United Kingdom","county":"","city":"Manchester","area":""},"after":{"country":"England","county":"Greater Manchester","city":"Manchester","area":""},"source_url":"https://worldathletics.org/athletes/-/14542604","evidence_ids":["geo-13","geo-14"]},{"slug":"wa-a40cfb90789e2f7a","before":{"country":"United Kingdom","county":"","city":"Bedford","area":""},"after":{"country":"England","county":"Bedfordshire","city":"Bedford","area":""},"source_url":"https://worldathletics.org/athletes/-/14542604","evidence_ids":["geo-269","geo-270"]}]$geography$::jsonb)
    AS c(slug text, before jsonb, after jsonb, source_url text, evidence_ids jsonb)
), eligible AS MATERIALIZED (
  SELECT e.*, c.after, c.evidence_ids FROM events e JOIN corrections c ON e.slug=c.slug
  WHERE e.country IS NOT DISTINCT FROM c.before->>'country'
    AND e.county IS NOT DISTINCT FROM c.before->>'county'
    AND e.city IS NOT DISTINCT FROM c.before->>'city'
    AND e.area IS NOT DISTINCT FROM c.before->>'area'
    AND e.source_url IS NOT DISTINCT FROM c.source_url
), backups AS (
  INSERT INTO app_meta(key,value)
  SELECT 'fixture-geography:2026-10-11:legacy:' || slug,
    jsonb_build_object('before',to_jsonb(eligible)-'after'-'evidence_ids',
      'after',after,'evidenceIds',evidence_ids,'checkedAt','2026-10-11')::text
  FROM eligible ON CONFLICT(key) DO NOTHING
  RETURNING key
)
UPDATE events e SET country=x.after->>'country', county=x.after->>'county',
  city=x.after->>'city', area=x.after->>'area', updated_at=now()
FROM eligible x WHERE e.id=x.id;
